public class Main {
    public static void main(String[] args) {
        int total = 7;
        System.out.println(total / 2);
        System.out.println(-total / 2);
        System.out.println(-total % 2);

        int count = 10;
        count /= 4;
        System.out.println(count);
        count += 0.9;
        System.out.println(count);

        byte small = 100;
        small *= 3;
        System.out.println(small);
    }
}
